In C, the best way to return an error from a function is to use an error code. This is typically done by defining a set of error codes and returning one of them from the function if an error occurs. Here's an example of how you might implement this:

```c
#include <stdio.h>

// Define error codes
#define SUCCESS 0
#define ERROR_INVALID_INPUT -1
#define ERROR_OUT_OF_RANGE -2

// Function that performs some operation and returns an error code
int performOperation(int input) {
    if (input < 0) {
        return ERROR_INVALID_INPUT; // Invalid input error
    } else if (input > 1000) {
        return ERROR_OUT_OF_RANGE; // Input out of range error
    }

    // Perform the operation (omitted for brevity)

    return SUCCESS; // Operation successful
}

int main() {
    int input = 1500; // Example input that will cause an error
    int result = performOperation(input);

    if (result != SUCCESS) {
        printf("Error occurred: %d\n", result);
    } else {
        printf("Operation successful.\n");
    }

    return 0;
}
```

